{
  "technical_and_design_decisions": [
    "Use Spring Boot Security starter to provide Basic Auth in spring-xd-dirt (U1).",
    "Default server.basic.enabled=false in application.yml to maintain backward compatibility.",
    "Single-user security configuration will be supplied via servers.yml and mapped to Spring Boot security properties (U2).",
    "XD Shell admin config command will be extended with --username and --password, which will be sent as HTTP Basic Authorization header (U3).",
    "Upgrade project dependencies to latest Spring Boot 1.1.x (RELEASE used as default, snapshot available via build profile) to inherit OOTB security (U4, U5).",
    "REST API for pushing archive (U6) is treated as a spike only; deliver design doc and stories, no implementation in this increment.",
    "Docker images based on Ubuntu with Java 7 and full XD jar; sandbox image includes Redis and RabbitMQ, production image excludes them (U7, U8)."
  ],
  "assumptions": [
    "Existing Spring XD project structure and build system (e.g., Gradle) are in place and familiar to the developer.",
    "Target Spring Boot version is 1.1.x as referenced in the stories, compatible with Java 7.",
    "The 'full XD jar' is already built and available to copy into Docker images.",
    "Developer has local Docker environment for building and testing images.",
    "Effort estimates include writing minimal unit tests but exclude extensive manual customer testing.",
    "Servers.yml and application.yml are standard Spring Boot externalized config files already supported by the project.",
    "All estimates are in workdays (8-hour days) representing most likely effort for a single developer."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Update Spring Boot dependencies",
      "activity_description": "Modify build configuration to pull latest Spring Boot 1.1.x RELEASE (and snapshot profile) and add spring-boot-starter-security to spring-xd-dirt project (covers U4, U5, part of U1).",
      "most_likely_effort": 1
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Implement Basic Auth option",
      "activity_description": "Enable Basic Auth via Spring Boot security starter in spring-xd-dirt, controlled by server.basic.enabled property with default false in application.yml; verify challenge/response (U1).",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Single-user security configuration",
      "activity_description": "Allow overriding of single-user security settings through servers.yml, mapping to Spring Boot security properties (U2).",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "XD Shell admin config credentials",
      "activity_description": "Add --username and --password options to admin config command in XD Shell; store and use for Basic Auth against secured admin server (U3).",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "REST API archive push spike",
      "activity_description": "Assess requirement, brainstorm options, document design, socialize with team, identify phases, create new stories. Research only, no implementation (U6).",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Sandbox Docker image",
      "activity_description": "Create Dockerfile with Ubuntu, Java 7, Redis, RabbitMQ, and full XD jar; build and test container (U7).",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Production-ready Docker image",
      "activity_description": "Create Dockerfile with Ubuntu, Java 7, and full XD jar; build and test container (U8).",
      "most_likely_effort": 1
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Integration testing and documentation",
      "activity_description": "Perform end-to-end tests of secured admin server with shell, validate Docker images, write user/ops documentation.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 15
  }
}

